//! Drives the fixture crate the way a real user would: `cargo build`, then
//! inspect the generated files.
//!
//! The fixture is a single directory, so these tests serialise on one lock —
//! concurrent `cargo build` invocations in the same package would contend on
//! cargo's own lock and on the bindings directory.

use std::path::{Path, PathBuf};
use std::process::{Command, Output};
use std::sync::Mutex;

static FIXTURE: Mutex<()> = Mutex::new(());

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/demo")
}

fn build_fixture(extra_env: &[(&str, &str)]) -> Output {
    let mut cmd = Command::new(env!("CARGO"));
    cmd.arg("build").current_dir(fixture_dir());
    for (k, v) in extra_env {
        cmd.env(k, v);
    }
    cmd.output().expect("cargo build must run")
}

#[test]
fn cargo_build_generates_bindings_and_sweeps_stale_ones() {
    let _guard = FIXTURE.lock().unwrap_or_else(|e| e.into_inner());
    let dir = fixture_dir();
    let bindings = dir.join("bindings");
    let _ = std::fs::remove_dir_all(&bindings);

    let out = build_fixture(&[]);
    assert!(out.status.success(), "build failed: {}", String::from_utf8_lossy(&out.stderr));

    let user = std::fs::read_to_string(bindings.join("User.ts")).unwrap();
    assert!(user.starts_with("// @generated by ts-typegen -- DO NOT EDIT"));
    assert!(user.contains("userId: number;"), "rename_all not applied: {user}");
    assert!(user.contains("import type { Role } from \"./Role\";"));
    assert!(user.contains("nickname?: string | null;"), "skip_serializing_if not applied");
    assert!(!user.contains("secret"), "#[serde(skip)] field leaked into output");

    let role = std::fs::read_to_string(bindings.join("Role.ts")).unwrap();
    assert!(role.contains(r#""admin" | "guest""#), "got: {role}");

    let event = std::fs::read_to_string(bindings.join("Event.ts")).unwrap();
    assert!(event.contains(r#"kind: "click""#), "got: {event}");

    let page = std::fs::read_to_string(bindings.join("Page.ts")).unwrap();
    assert!(page.contains("Page<T>"), "generics lost: {page}");

    assert!(bindings.join("index.ts").is_file());

    // A stale generated file is swept; a hand-written one is not.
    std::fs::write(
        bindings.join("Ghost.ts"),
        "// @generated by ts-typegen -- DO NOT EDIT\nexport type Ghost = null;\n",
    )
    .unwrap();
    std::fs::write(bindings.join("handwritten.ts"), "export const x = 1;\n").unwrap();
    touch_source();
    assert!(build_fixture(&[]).status.success());
    assert!(!bindings.join("Ghost.ts").exists(), "stale generated file must be swept");
    assert!(bindings.join("handwritten.ts").is_file(), "hand-written file must survive");
    std::fs::remove_file(bindings.join("handwritten.ts")).unwrap();
}

#[test]
fn check_mode_fails_when_bindings_are_stale() {
    let _guard = FIXTURE.lock().unwrap_or_else(|e| e.into_inner());
    assert!(build_fixture(&[]).status.success());
    let path = fixture_dir().join("bindings/User.ts");
    let original = std::fs::read_to_string(&path).unwrap();
    std::fs::write(&path, original.replace("userId: number;", "userId: string;")).unwrap();

    let out = build_fixture(&[("TS_TYPEGEN_CHECK", "1")]);
    assert!(!out.status.success(), "check mode must fail on drift");
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("out of date"), "got: {stderr}");

    std::fs::write(&path, original).unwrap();
    touch_source();
    assert!(build_fixture(&[]).status.success());
}

#[test]
fn generated_typescript_compiles() {
    let _guard = FIXTURE.lock().unwrap_or_else(|e| e.into_inner());
    if Command::new("npx").arg("--version").output().is_err() {
        eprintln!("skipping generated_typescript_compiles: npx not available");
        return;
    }
    assert!(build_fixture(&[]).status.success());
    let out = Command::new("npx")
        .args([
            "--yes",
            "--package",
            "typescript@5",
            "--",
            "tsc",
            "--noEmit",
            "--strict",
            "bindings/index.ts",
        ])
        .current_dir(fixture_dir())
        .output()
        .expect("npx must run");
    assert!(
        out.status.success(),
        "tsc rejected generated output:\n{}\n{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
}

/// Cargo only reruns the build script when a scan root changes.
fn touch_source() {
    let p = fixture_dir().join("src/user.rs");
    let text = std::fs::read_to_string(&p).unwrap();
    std::fs::write(&p, text).unwrap();
}
